module carry_lookahead_16bit(
    input [16:1] A,
    input [16:1] B,
    input Cin,
    output [16:1] S,
    output Cout
);

    wire [3:0] P;
    wire [3:0] G;
    wire [3:0] C;
    wire [16:1] S_int;

    // Generate P and G for each 4-bit segment
    genvar i;
    generate
        for(i=0; i<4; i=i+1) begin : gen_4bit_cla
            assign P[i] = A[i*4+3] | B[i*4+3];
            assign G[i] = A[i*4+3] & B[i*4+3];
        end
    endgenerate

    // Generate C for each 4-bit segment
    assign C[0] = Cin;
    assign C[1] = G[0] | (P[0] & C[0]);
    assign C[2] = G[1] | (P[1] & C[1]);
    assign C[3] = G[2] | (P[2] & C[2]);

    // 4-bit CLA blocks
    genvar j;
    generate
        for(j=0; j<4; j=j+1) begin : gen_4bit_blocks
            cla_block cla_4bit (
                .A(A[j*4+3:j*4+1]),
